# Cell 14: numerical grid helpers; plotting implementations live in plotting.py.
from plotting import plot_phase1_absolute_m_heatmaps, plot_phase1_oversampling_heatmaps
def _phase1_error_to_float(value):
    try: return float(value)
    except Exception:
        try: return float(mp.mpf(str(value)))
        except Exception: return np.nan
def phase1_make_heatmap_pairs(N_values,M_values,require_M_ge_N=True):
    return [(int(N),int(M)) for N in N_values for M in M_values if not require_M_ge_N or M>=N]
def phase1_make_oversampling_pairs(N_values,m_values,ref_extra=None):
    pairs={(int(N),int(N)+int(mm)) for N in N_values for mm in m_values}
    if ref_extra is not None: pairs.update((int(N),int(N)+int(ref_extra)) for N in N_values)
    return sorted(pairs)
def add_phase1_oversampling_columns(frame,ref_extra=None):
    '''Explanation: For a fixed N, increasing M tests whether quadrature error has become negligible compared with truncation error. The excess ratios reveal this stabilisation without converting it into a rigorous remainder bound.
Functionality: Add Phase 1 oversampling offsets and finite-M excess ratios relative to each truncation's largest sampled M.'''
    out=frame.copy(); out['N']=out.N.astype(int); out['M']=out.M.astype(int); out['m']=out.M-out.N
    out['is_reference_M']=out.m.eq(int(ref_extra)) if ref_extra is not None else False; return out
def add_phase1_reference_error_ratios(frame):
    '''Explanation: Dividing observed errors by an empirical reference curve makes deviations from the expected exponential trend easy to see. The ratio is interpretive evidence only, not a certified convergence constant.
Functionality: Normalise Phase 1 empirical errors by the displayed reference-error curve without promoting the ratio to a certificate.'''
    out=frame.copy(); out['error_float']=out.error.map(_phase1_error_to_float)
    ref=out[np.isfinite(out.error_float)&(out.error_float>0)].sort_values('M').groupby(['N','name']).tail(1).set_index(['N','name']).error_float
    out['reference_error_at_max_M']=[ref.get((row.N,row.name),np.nan) for row in out.itertuples()]
    out['excess_ratio_to_max_M']=out.error_float/out.reference_error_at_max_M
    out['log10_excess_ratio_to_max_M']=np.log10(out.excess_ratio_to_max_M)
    return out

